```

## Code changes

The struct, imports, and constructors:

```rust
use std::borrow::Borrow;
use std::hash::{BuildHasher, Hash, Hasher};

use ahash::RandomState;
use crossbeam_utils::CachePadded;
use hashbrown::HashMap;
use hashbrown::hash_map::RawEntryMut;
use parking_lot::RwLock;

pub struct ConcurrentMap<K, V, S = RandomState> {
    // CachePadded ensures each shard's lock word sits on its own cache line,
    // so atomic ops on shard A do not invalidate shard B's cache line.
    shards: Box<[CachePadded<RwLock<HashMap<K, V, S>>>]>,
    hasher: S,
    shard_mask: usize,
}

impl<K, V> ConcurrentMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    pub fn new() -> Self {
        Self::with_shards_and_capacity(default_shard_count(), 0)
    }

    pub fn with_capacity(capacity: usize) -> Self {
        Self::with_shards_and_capacity(default_shard_count(), capacity)
    }
}

impl<K, V, S> ConcurrentMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher + Clone,
{
    pub fn with_shards_and_hasher(shard_count: usize, hasher: S) -> Self {
        Self::with_parts(shard_count, 0, hasher)
    }

    pub fn with_shards_and_capacity(shard_count: usize, capacity: usize) -> Self
    where
        S: Default,
    {
        Self::with_parts(shard_count, capacity, S::default())
    }

    fn with_parts(shard_count: usize, capacity: usize, hasher: S) -> Self {
        let shard_count = shard_count.max(1).next_power_of_two();
        let per_shard = capacity.div_ceil(shard_count);
        let shards: Vec<_> = (0..shard_count)
            .map(|_| {
                CachePadded::new(RwLock::new(HashMap::with_capacity_and_hasher(
                    per_shard,
                    hasher.clone(),
                )))
            })
            .collect();
        Self {
            shards: shards.into_boxed_slice(),
            hasher,
            shard_mask: shard_count - 1,
        }
    }

    #[inline]
    fn hash_of<Q>(&self, key: &Q) -> u64
    where
        Q: Hash + ?Sized,
    {
        let mut h = self.hasher.build_hasher();
        key.hash(&mut h);
        h.finish()
    }

    #[inline]
    fn shard_for(&self, hash: u64) -> &RwLock<HashMap<K, V, S>> {
        // Use the high bits for shard selection; hashbrown uses the low bits
        // for bucket indexing, so this avoids correlating the two.
        let idx = (hash >> (u64::BITS - self.shard_mask.count_ones())) as usize;
        &self.shards[idx]
    }
}
```

The hot-path methods, now hashing once and using `raw_entry`:

```rust
impl<K, V, S> ConcurrentMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher + Clone,
{
    pub fn insert(&self, key: K, value: V) -> Option<V> {
        let hash = self.hash_of(&key);
        let mut shard = self.shard_for(hash).write();
        match shard.raw_entry_mut().from_key_hashed_nocheck(hash, &key) {
            RawEntryMut::Occupied(mut o) => Some(std::mem::replace(o.get_mut(), value)),
            RawEntryMut::Vacant(v) => {
                v.insert_hashed_nocheck(hash, key, value);
                None
            }
        }
    }

    pub fn remove<Q>(&self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash_of(key);
        let mut shard = self.shard_for(hash).write();
        match shard.raw_entry_mut().from_key_hashed_nocheck(hash, key) {
            RawEntryMut::Occupied(o) => Some(o.remove()),
            RawEntryMut::Vacant(_) => None,
        }
    }

    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash_of(key);
        let shard = self.shard_for(hash).read();
        shard
            .raw_entry()
            .from_key_hashed_nocheck(hash, key)
            .is_some()
    }

    pub fn get<Q>(&self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        V: Clone,
    {
        let hash = self.hash_of(key);
        let shard = self.shard_for(hash).read();
        shard
            .raw_entry()
            .from_key_hashed_nocheck(hash, key)
            .map(|(_, v)| v.clone())
    }

    pub fn with<Q, F, R>(&self, key: &Q, f: F) -> Option<R>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        F: FnOnce(&V) -> R,
    {
        let hash = self.hash_of(key);
        let shard = self.shard_for(hash).read();
        shard
            .raw_entry()
            .from_key_hashed_nocheck(hash, key)
            .map(|(_, v)| f(v))
    }

    pub fn with_mut<Q, F, R>(&self, key: &Q, f: F) -> Option<R>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        F: FnOnce(&mut V) -> R,
    {
        let hash = self.hash_of(key);
        let mut shard = self.shard_for(hash).write();
        match shard.raw_entry_mut().from_key_hashed_nocheck(hash, key) {
            RawEntryMut::Occupied(mut o) => Some(f(o.get_mut())),
            RawEntryMut::Vacant(_) => None,
        }
    }
}
```

A few smaller call-site updates round it out. With `parking_lot`, `read()`/`write()` no longer return `Result`, so all the `.expect("shard poisoned")` calls go away:

```rust
    pub fn len(&self) -> usize {
        self.shards.iter().map(|s| s.read().len()).sum()
    }

    pub fn is_empty(&self) -> bool {
        self.shards.iter().all(|s| s.read().is_empty())
    }

    pub fn clear(&self) {
        for shard in self.shards.iter() {
            shard.write().clear();
        }
    }
```

## When to push further

If your workload is *almost entirely* reads with rare writes (config tables, routing tables, feature flags), even a sharded `RwLock` will lose to a fully lock-free read path. Two paths from here:

- **`arc_swap::ArcSwap<HashMap<...>>`** per shard. Readers do an atomic load of an `Arc`, no lock at all. Writers clone the inner map, mutate, and `swap`. Reads become wait-free; writes get O(shard_size) more expensive and allocate. Worth it when read:write ratio is, say, > 10000:1.
- **`left-right`** (the `left_right` crate). Readers see a stable snapshot through a per-thread epoch; writers apply ops to a shadow copy and publish. Wait-free reads with bounded write amplification, at the cost of a more involved API.

Both are bigger architectural changes than this PR-sized refactor, so I'd reach for them only after measuring that the sharded `RwLock` is actually the bottleneck. For most "high read contention" workloads, the four changes above (cache padding, `parking_lot`, hash-once, faster hasher) close most of the gap with `dashmap` while keeping the implementation small.
